 public function testApprovedMultiplePhotoSlotsReproduceBothSourcesInFinalAndPreview(string $engine):void {
  $input=$this->deterministicFixture($engine,[['position'=>'front','decoration_method'=>'dtg','width_px'=>4,'height_px'=>2,'dpi'=>300,'qa_geometry'=>['safe_zone'=>['x'=>0,'y'=>0,'width'=>4,'height'=>2],'seam_exclusions'=>[],'min_image_dpi'=>300]]]);
  $paths=[];$verifier=new DigiForge\POD\RenderArtifactVerifier();$store=new DigiForge\POD\RenderArtifactStore();
  $left="\xff\0\0\xff\0\0\xff\xff\0\xff\0\xff\0\0\0\xff";
  $right="\xff\xff\0\xff\0\xff\xff\xff\xff\0\xff\xff\xff\xff\xff\xff";
  try {
   $sources=[];foreach([$left,$right]as $pixels){$path=tempnam(sys_get_temp_dir(),'df-multi-photo-');$paths[]=$path;file_put_contents($path,DigiForge\POD\RasterArtworkCodec::encode(2,2,$pixels));$source=$store->retain($path,$verifier->readArtifact($path));self::assertNotWPError($source);$sources[]=$source;}
   self::assertNotSame($sources[0]['storage_reference'],$sources[1]['storage_reference']);
   global $wpdb;$tables=DigiForge\Database\Tables::class;
   $submission=$wpdb->get_row($wpdb->prepare('SELECT * FROM '.$tables::personalization_submissions().' WHERE payload_hash=%s',$input['personalization_evidence_hash']),ARRAY_A);self::assertIsArray($submission);
   self::assertSame(1,$wpdb->update($tables::personalization_schemas(),['field_definitions'=>'[{"key":"photo","type":"image_reference"},{"key":"photo_right","type":"image_reference"}]'],['id'=>$submission['personalization_schema_id']]));
   $payload=DigiForge\Orders\Validator::canonicalJson(['photo'=>$sources[0]['storage_reference'],'photo_right'=>$sources[1]['storage_reference']]);
   self::assertSame(1,$wpdb->update($tables::personalization_submissions(),['canonical_payload'=>$payload,'payload_hash'=>hash('sha256',$payload)],['id'=>$submission['id']]));$input['personalization_evidence_hash']=hash('sha256',$payload);
   $recipe=['engine'=>$engine,'background'=>'#ffffff','slots'=>[['type'=>'image','field'=>'photo','x'=>0,'y'=>0,'width'=>2,'height'=>2],['type'=>'image','field'=>'photo_right','x'=>2,'y'=>0,'width'=>2,'height'=>2]]];
   $renderer=new DigiForge\POD\DeterministicPersonalizationRenderer();self::assertNotWPError($renderer->approveRecipe($input['template_key'],1,$recipe));
   $expected=$renderer->expected($input);self::assertNotWPError($expected);self::assertSame(2,substr_count($expected['svg'],'<image '));
   foreach($paths as $path)self::assertStringContainsString('data:image/png;base64,'.base64_encode(file_get_contents($path)),$expected['svg']);
   self::assertSame($expected['sha256'],$renderer->expected($input)['sha256']);
   $pixels=substr($left,0,8).substr($right,0,8).substr($left,8,8).substr($right,8,8);
   $workflow=new DigiForge\POD\DeterministicRenderWorkflow();
   foreach(['png','pdf']as $format){
