 private function unapprovedVisualCutout(array $original):array {
  $key='independent-'.wp_generate_uuid4();$source=tempnam(sys_get_temp_dir(),'df-vr-test-');$mask=DigiForge\ProductFactory\AssetStorage::absolutePath($original['mask']['storage_reference']);$rgba=DigiForge\POD\RasterArtworkCodec::decode(file_get_contents(DigiForge\ProductFactory\AssetStorage::absolutePath($original['source']['storage_reference'])))['rgba'];$rgba[(20*64+20)*4]=chr(ord($rgba[(20*64+20)*4])^128);file_put_contents($source,DigiForge\POD\RasterArtworkCodec::encode(64,64,$rgba));try{$record=(new DigiForge\POD\CustomerCutoutRepository())->ingest('personalized_pod',$key,$original['order_id'],$source,$mask,$original['rights'],'CS01',[]);}finally{unlink($source);}self::assertNotWPError($record);return [$key,$record];
 }
 private function independentApproval(array $record,string $key,array $flags):array|WP_Error {
  $repo=new DigiForge\POD\CustomerCutoutRepository();if($record['style']==='SOURCE_PHOTO')return $repo->approve('personalized_pod',$key,$flags);
  $operator=get_current_user_id();$review=new DigiForge\POD\CutoutVisualReviewRepository();$request=$this->visualCase($record,$key);$case=$review->intake($request);self::assertNotWPError($case);$reviewer=self::factory()->user->create(['role'=>'administrator']);$assignment=$review->assign('personalized_pod',$request['case_key'],$case['sha256'],$reviewer);self::assertNotWPError($assignment);
  wp_set_current_user($reviewer);try{$decision=$review->decide('personalized_pod',$request['case_key'],$assignment['sha256'],'APPROVE',$flags,[]);self::assertNotWPError($decision);return $repo->approve('personalized_pod',$key,$flags);}finally{wp_set_current_user($operator);}
 }
 private function visualCase(array $record,string $cutout,?string $caseKey=null,?string $parent=null,?string $matte=null):array {
  $source=$record['segmentation']['original_source']??$record['source'];$mask=$matte??file_get_contents(DigiForge\ProductFactory\AssetStorage::absolutePath($record['mask']['storage_reference']));$rights=[];$root=wp_upload_dir()['basedir'].'/digiforge/product-factory/pod-review-evidence/shop-personalized_pod';wp_mkdir_p($root);
  foreach(['source_rights','source_consent','reference_rights','reference_consent']as $kind){$reference='digiforge/product-factory/pod-review-evidence/shop-personalized_pod/'.wp_generate_uuid4().'.json';$body=json_encode(['schema'=>1,'shop_key'=>'personalized_pod','order_id'=>$record['order_id'],'asset_sha256'=>str_starts_with($kind,'source')?$source['sha256']:hash('sha256',$mask),'kind'=>$kind,'local_review_permitted'=>true,'evidence_kind'=>'SYNTHETIC_TEST_ONLY','declaration'=>'Synthetic software fixture only; no real licensing or customer consent.']);file_put_contents(wp_upload_dir()['basedir'].'/'.$reference,$body);$rights[$kind]=['storage_reference'=>$reference,'sha256'=>hash('sha256',$body)];}
  return ['shop_key'=>'personalized_pod','case_key'=>$caseKey??'visual-'.wp_generate_uuid4(),'cutout_key'=>$cutout,'source_sha256'=>$source['sha256'],'subject_type'=>'human','reference_base64'=>base64_encode($mask),'reference_sha256'=>hash('sha256',$mask),'reference_kind'=>'SYNTHETIC_TEST_ONLY','rights'=>$rights,'supersedes'=>$parent];
 }
