 private function mockupRecipeFixture(array $render,string $family,int $version,?string $key=null):array {
  $key=$key??'mockup-'.wp_generate_uuid4();$layers=['base'=>str_repeat("\x20\x40\x60\xff",64),'lighting'=>str_repeat("\x80\x80\x80\xff",64),'u'=>'','v'=>'','coverage'=>''];for($y=0;$y<8;$y++)for($x=0;$x<8;$x++){$layers['u'].=pack('n',intdiv($x*65535,7))."\0\xff";$layers['v'].=pack('n',intdiv($y*65535,7))."\0\xff";$c=$x>0&&$x<7&&$y>0&&$y<7?255:0;$layers['coverage'].=str_repeat(chr($c),3)."\xff";}$assets=[];foreach($layers as $name=>$rgba){$p=tempnam(sys_get_temp_dir(),'df-mockup-layer-');file_put_contents($p,DigiForge\POD\RasterArtworkCodec::encode(8,8,$rgba));try{$m=(new DigiForge\POD\RenderArtifactVerifier())->readArtifact($p);self::assertNotWPError($m);$registered=(new DigiForge\POD\ProductMockupRegistry())->registerAsset(base64_encode(file_get_contents($p)),$m['sha256']);self::assertNotWPError($registered);$assets[$name]=$registered['asset'];}finally{unlink($p);}}$root=wp_upload_dir()['basedir'].'/';$licenseRef='digiforge/product-factory/pod-mockup-license/shop-personalized_pod/'.wp_generate_uuid4().'.txt';wp_mkdir_p(dirname($root.$licenseRef));file_put_contents($root.$licenseRef,'SYNTHETIC TEST ONLY. No actual product assets, licenses, rights or certification.');$rights=['schema'=>2,'shop_key'=>'personalized_pod','recipe_key'=>$key,'recipe_version'=>$version,'evidence_kind'=>'SYNTHETIC_TEST_ONLY','asset_sha256'=>array_map(static fn($a)=>$a['sha256'],$assets),'customer_display_permitted'=>true,'derivative_projection_permitted'=>true,'license_document_reference'=>$licenseRef,'license_document_sha256'=>hash_file('sha256',$root.$licenseRef)];$rightsRef='digiforge/product-factory/pod-mockup-rights/shop-personalized_pod/'.wp_generate_uuid4().'.json';wp_mkdir_p(dirname($root.$rightsRef));file_put_contents($root.$rightsRef,json_encode($rights));$template=(new DigiForge\POD\RenderArtifactVerifier())->certifiedTemplate($render);self::assertNotWPError($template);global $wpdb;$attrs=$wpdb->get_var($wpdb->prepare('SELECT c.attributes FROM '.DigiForge\Database\Tables::pod_cat