  $input=$this->deterministicFixture('AOP_PATTERN',[$this->familyArea()]);[$unused,$manual,$doc]=$this->familyCutout($input['order_id']);$repo=new DigiForge\POD\CustomerCutoutRepository();$workflow=new DigiForge\POD\PersonalizedDesignWorkflow();$rights=$manual['rights'];$rights['segmentation_method']=DigiForge\POD\ExperimentalMattingPipeline::METHOD;
