  try{
   self::assertWPError($workflow->segmentUpload(array_replace($upload,['shop_key'=>'digital'])));self::assertWPError($workflow->segmentUpload($upload+['model'=>'untrusted']));self::assertWPError($workflow->segmentUpload(array_replace($upload,['order_id'=>$input['order_id']+900000])));$user=get_current_user_id();wp_set_current_user(self::factory()->user->create(['role'=>'subscriber']));self::assertWPError($workflow->segmentUpload($upload));wp_set_current_user($user);
   $record=$workflow->segmentUpload($upload);self::assertNotWPError($record);self::assertSame('REVIEW_REQUIRED',$record['state']);self::assertFalse($record['commercial_certified']);self::assertSame($record,$workflow->segmentUpload($upload));self::assertGreaterThan(0,$record['segmentation']['soft_alpha_pixels']);self::assertSame('NOT_CERTIFIED',$record['segmentation']['certification']);self::assertNotWPError($repo->read('personalized_pod',$upload['key']));self::assertWPError($repo->assertForOrder('personalized_pod',$input['order_id'],$record['result']['storage_reference']));
   $review=array_fill_keys(['missing_head','clipped_features','halo','low_contrast','fragmented_mask','low_resolution','blurred_features','missing_hair_ears_whiskers'],false);self::assertWPError($repo->approve('personalized_pod',$upload['key'],$review));$review+=array_fill_keys(['background_contamination','unnatural_soft_alpha','foreground_color_damage'],false);self::assertWPError($repo->approve('personalized_pod',$upload['key'],array_replace($review,['background_contamination'=>true])));self::assertNotWPError($this->independentApproval($record,$upload['key'],$review));self::assertNotWPError($repo->assertForOrder('personalized_pod',$input['order_id'],$record['result']['storage_reference']));self::assertWPError($repo->assertForOrder('digital',$input['order_id'],$record['result']['storage_reference']));
   $draft=DigiForge\POD\DesignFamilyLibrary::draft($this->familyTemplate($input),'FR01',['background'=>'#ffffff','text_color'=>'#000000','font_size'=>10,'face_fields'=>['face_1'],'tile_width'=>16,'tile_height'=>16,'spacing_percent'=>100,'rotations'=>[0,90],'include_name'=>false]);$this->familyPayload($input,$draft['schema'],['face_1'=>$record['result']['storage_reference']]);$renderer=new DigiForge\POD\DeterministicPersonalizationRenderer();delete_option('digiforge_render_recipe_'.$input['template_sha256']);self::assertNotWPError($renderer->approveRecipe($input['template_key'],1,$draft['recipe']));$expected=$renderer->expected($input);self::assertNotWPError($expected);self::assertSame($expected,$renderer->expected($input));
   $path=DigiForge\ProductFactory\AssetStorage::absolutePath($record['segmentation']['original_source']['storage_reference']);$bytes=file_get_contents($path);try{file_put_contents($path,'changed original');self::assertWPError($repo->read('personalized_pod',$upload['key']));self::assertWPError($renderer->expected($input));}finally{file_put_contents($path,$bytes);}
  }finally{unlink($doc);}
